mapper.select:
select
c.*,
co.name as course_name
from customer c
left join courses co on c.course_id = co.id


        and c.phone = #{customerQueryDto.phone}


        and c.name like concat('%', #{customerQueryDto.name}, '%')


        and c.channel = #{customerQueryDto.channel}


        and c.subject = #{customerQueryDto.subject}


order by c.update_time desc
